cd /app && cat > /app/final.mjs <<'EOF'
import { EC2Client, DescribeInstancesCommand } from '@aws-sdk/client-ec2';
import { fromTemporaryCredentials } from '@aws-sdk/credential-providers';
import { S3Client, GetObjectCommand, ListObjectsV2Command } from '@aws-sdk/client-s3';
const B='metering-metering-cadence', dimensionId='dim-uptime-sandbox', INC=0.08333333;
const s3=new S3Client({});
const getDoc=async k=>{const{Body}=await s3.send(new GetObjectCommand({Bucket:B,Key:k}));return JSON.parse(await Body.transformToString());};
const listKeys=async p=>{const r=await s3.send(new ListObjectsV2Command({Bucket:B,Prefix:p}));return(r.Contents??[]).map(c=>c.Key).filter(k=>!k.endsWith('/'));};
const registry=await getDoc('onboarding/registry.json');
const customers=await Promise.all((await listKeys(registry.customerRecordPrefix)).map(getDoc));
const tenants={},ded={};
for(const c of customers)for(const a of c.accounts??[]){(tenants[a.accountId]??=new Set()).add(c.customerId);if(a.dedicated)ded[a.accountId]=c.customerId;}
const billing={};
for(const a of registry.accounts){const ts=tenants[a.accountId]??new Set();billing[a.accountId]={tenants:[...ts].sort(),dedicatedTo:(ded[a.accountId]&&ts.size===1)?ded[a.accountId]:undefined};}
const readAccount=async account=>{
  const creds=fromTemporaryCredentials({params:{RoleArn:account.roleArn,ExternalId:account.externalId||undefined},clientConfig:{region:'us-east-1'}});
  const c=new EC2Client({region:account.region,credentials:creds});
  const r=await c.send(new DescribeInstancesCommand({Filters:[{Name:'instance-state-name',Values:['running']},{Name:'tag-key',Values:['meteringDimensionId']}]}));
  let list=[];for(const res of r.Reservations??[])list=list.concat(res.Instances??[]);
  return list.filter(i=>{const d=(i.Tags??[]).find(x=>x.Key==='meteringDimensionId');return d&&d.Value.split(',').includes(dimensionId);})
    .map(i=>({accountId:account.accountId,instanceId:i.InstanceId,tags:(i.Tags??[]).reduce((a,{Key,Value})=>{a[Key]=Value;return a;},{})}));
};
const collected=[];for(const a of registry.accounts)collected.push(...await readAccount(a));
const rt={},ids={};
const credit=(c,id,s)=>{rt[c]=(rt[c]??0)+INC*s;(ids[c]??=new Set()).add(id);};
for(const i of collected){
  const b=billing[i.accountId]??{tenants:[]};
  if(b.dedicatedTo){credit(b.dedicatedTo,i.instanceId,1);continue;}
  const tagged=(i.tags.meteringCustomerId??'').split(',').map(x=>x.trim()).filter(Boolean);
  const billable=[...new Set(tagged.filter(id=>b.tenants.includes(id)))];
  if(!billable.length)continue;
  const s=1/billable.length;billable.forEach(c=>credit(c,i.instanceId,s));
}
console.log('FINAL PUBLISHED UPTIME:');
for(const c of Object.keys(rt).sort())console.log(' ',c,'=',rt[c].toFixed(8),'instances:',[...ids[c]].sort().join(','));
process.exit(0);
EOF
timeout 25 node /app/final.mjs 2>&1; rm -f /app/final.mjs

